'use strict';
// node tools/music/build-manifest.js
//
// Builds the two GENERATED files from each game's own small files, so games can be worked on
// in parallel without ever editing the same file:
//
//   public/audio/music/games/<key>/music.json   { "cues": { "<cue>": { file, loopStart?, loopEnd?, gain? } | "<file>" },
//                                                 "credits": [{ file, title, author, source, license }] }
//                                               file paths are relative to public/audio/music/
//   public/audio/sfx/<key>/credits.json          [{ file, title, author, source, license }]   (file relative to public/audio/sfx/)
//
//   -> public/audio/music/manifest.json   games.<key> = that game's cues (other top-level keys are kept)
//   -> public/audio/CREDITS.md            every recorded track and sound effect with its author, source and license
//
// Only commercially safe licenses are accepted (CC0 / public domain / CC-BY / OGA-BY / Pixabay /
// Kenney CC0 / "original"); anything else stops the build. Run it after adding or changing a game's
// music or sounds (tools/test-music-files.js checks the outputs are up to date).
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.join(__dirname, '..', '..');
const MUSIC = path.join(ROOT, 'public', 'audio', 'music');
const SFX = path.join(ROOT, 'public', 'audio', 'sfx');
const OK_LICENSE = /^(CC0( 1\.0)?|Public domain|CC-BY [34]\.0|CC BY [34]\.0|OGA-BY 3\.0|Pixabay Content License|Original)$/i;

const readJson = (f) => JSON.parse(fs.readFileSync(f, 'utf8'));
const dirs = (d) => (fs.existsSync(d) ? fs.readdirSync(d, { withFileTypes: true }).filter((e) => e.isDirectory()).map((e) => e.name).sort() : []);
const problems = [];

function checkCredits(list, base, where) {
  if (!Array.isArray(list)) { problems.push(where + ': credits must be an array'); return []; }
  for (const c of list) {
    if (!c || !c.file || !c.title || !c.author || !c.source || !c.license) problems.push(where + ': credit needs file, title, author, source, license: ' + JSON.stringify(c));
    else {
      if (!OK_LICENSE.test(String(c.license).trim())) problems.push(where + ': license not allowed for a paid game: ' + c.license + ' (' + c.file + ')');
      if (!fs.existsSync(path.join(base, c.file))) problems.push(where + ': credited file missing: ' + c.file);
    }
  }
  return list;
}

function build() {
  const manFile = path.join(MUSIC, 'manifest.json');
  const man = fs.existsSync(manFile) ? readJson(manFile) : {};
  const games = {};
  const credits = [];
  for (const key of dirs(path.join(MUSIC, 'games'))) {
    const f = path.join(MUSIC, 'games', key, 'music.json');
    if (!fs.existsSync(f)) continue;
    const m = readJson(f);
    const cues = m.cues || {};
    for (const [cue, v] of Object.entries(cues)) {
      const file = typeof v === 'string' ? v : v && v.file;
      if (!file || !fs.existsSync(path.join(MUSIC, file))) problems.push(`music ${key}.${cue}: file missing: ${file}`);
    }
    games[key] = cues;
    for (const c of checkCredits(m.credits || [], MUSIC, 'music ' + key)) credits.push({ kind: 'Music', game: key, ...c });
  }
  for (const key of dirs(SFX)) {
    const f = path.join(SFX, key, 'credits.json');
    if (!fs.existsSync(f)) continue;
    for (const c of checkCredits(readJson(f), SFX, 'sfx ' + key)) credits.push({ kind: 'Sound effect', game: key, ...c });
  }
  // keep any hand-made top-level sections (sets, aliases, mafia), replace games wholesale
  const out = { _doc: 'GENERATED by tools/music/build-manifest.js from public/audio/music/games/<key>/music.json. Do not edit by hand.', ...man, games: { ...((man.games && man.games._default) ? { _default: man.games._default } : {}), ...games } };
  out._doc = 'GENERATED by tools/music/build-manifest.js from public/audio/music/games/<key>/music.json. Do not edit by hand.';
  const md = ['# Recorded music and sound effects', '', 'GENERATED by `tools/music/build-manifest.js` from each game\'s `music.json` / `credits.json`. Do not edit by hand.', '',
    'Every file is free for commercial use under the license listed. CC-BY / OGA-BY entries require this credit to ship with the game.', '',
    '| Game | Kind | File | Title | Author | License | Source |', '|---|---|---|---|---|---|---|',
    ...credits.map((c) => `| ${c.game} | ${c.kind} | \`${c.file}\` | ${c.title} | ${c.author} | ${c.license} | ${c.source} |`), ''].join('\n');
  return { manifest: JSON.stringify(out, null, 1) + '\n', credits: md, problems };
}

if (require.main === module) {
  const r = build();
  if (r.problems.length) { console.error('Music/SFX problems:\n  ' + r.problems.join('\n  ')); process.exit(1); }
  fs.writeFileSync(path.join(MUSIC, 'manifest.json'), r.manifest);
  fs.writeFileSync(path.join(ROOT, 'public', 'audio', 'CREDITS.md'), r.credits);
  console.log('manifest + CREDITS.md written');
}
module.exports = { build };
